fn generate_random_tensor(shape: List(Int)) -> Tensor {
  let size = list.fold(shape, 1, fn(acc, dim) { acc * dim })
  let data = list.init(size, fn(_) { random.float() })
  dynamic.from(data)
}

pub fn init_spline(
  grid_size: Int,
  spline_order: Int,
  coeff_dim: Int,
) -> Spline {
  let num_coeffs = grid_size + spline_order
  Spline(
    coefficients: generate_random_tensor([coeff_dim, num_coeffs]),
    knots: dynamic.from(
      list.range(0, num_coeffs)
      |> list.map(fn(i) { int.to_float(i) /. int.to_float(grid_size) }),
    ),
    grid_size: grid_size,
    spline_order: spline_order,
  )
}

