  input_dim: Int,
  output_dim: Int,
  grid_size: Int,
  spline_order: Int,
) -> KanLayer {
  KanLayer(
    input_dim: input_dim,
    output_dim: output_dim,
    splines: list.init(input_dim * output_dim, fn(_) {
      init_spline(grid_size, spline_order, 1)
    }),
    base_weights: generate_random_tensor([input_dim, output_dim]),
    spline_weights: generate_random_tensor([input_dim, output_dim]),
  )
}

