pub fn kan_layer_forward(layer: KanLayer, input: Tensor) -> Tensor {
  // This is a conceptual implementation.
  // A real implementation would require tensor operations not native to Gleam.
  let base_output = dynamic.from("matmul(input, layer.base_weights)")
  let spline_output = dynamic.from("evaluate_splines(layer.splines, input)")
  let scaled_spline =
    dynamic.from("spline_output * layer.spline_weights")

  dynamic.from_string(
    "base_output + scaled_spline",
  )
}

pub fn ssm_layer_forward(layer: SsmLayer, input: Tensor) -> #(
  SsmLayer,
  Tensor,
) {
  // This is a conceptual implementation of the SSM recurrence.
  // x_new = A * x + B * u
  // y = C * x_new + D * u
  let u = input
  let x = layer.hidden_state
  let a = layer.state.a_matrix
  let b = layer.state.b_matrix
  let c = layer.state.c_matrix
  let d = layer.d_matrix

  let x_new = dynamic.from_string("matmul(a, x) + matmul(b, u)")
  let y = dynamic.from_string("matmul(c, x_new) + matmul(d, u)")

  let new_layer = SsmLayer(..layer, hidden_state: x_new)
  #(new_layer, y)
}

pub fn hybrid_layer_forward(layer: HybridLayer, input: Tensor) -> #(
  HybridLayer,
  Tensor,
) {
  // Residual connection path
  let residual = input

  // First sub-layer: KAN
  let kan_out =
    input
    |> layer.norm1
    |> kan_layer_forward(layer.kan_layer, _)

  // Add residual
  let post_kan = dynamic.from_string("kan_out + residual")

  // Second sub-layer: SSM
  let #(new_ssm_layer, ssm_out) =
    post_kan
    |> layer.norm2
    |> ssm_layer_forward(layer.ssm_layer, _)

  let new_hybrid_layer = HybridLayer(..layer, ssm_layer: new_ssm_layer)

  // Final residual connection for the layer
  let output = dynamic.from_string("ssm_out + post_kan")

  #(new_hybrid_layer, output)
}

